var modrinthProvider = {
  type: "modrinth",
  displayName: "Modrinth App",
  async isInstalled() {
    return getModrinthDataPath() !== null;
  },
  getDataPath() {
    return getModrinthDataPath();
  },
  async discoverInstances() {
    const dataPath = getModrinthDataPath();
    if (!dataPath)
      return [];
    const profilesDir = path5.join(dataPath, "profiles");
    if (!fs5.existsSync(profilesDir))
      return [];
    const profileMetadata = getProfilesFromDb(dataPath);
    const instances = [];
    try {
      const entries = fs5.readdirSync(profilesDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory())
          continue;
        if (entry.name.startsWith("."))
          continue;
        const minecraftPath = path5.join(profilesDir, entry.name);
        const hasSaves = fs5.existsSync(path5.join(minecraftPath, "saves"));
        const hasMods = fs5.existsSync(path5.join(minecraftPath, "mods"));
        if (!hasSaves && !hasMods)
          continue;
        const metadata = profileMetadata.get(entry.name);
        instances.push({
          id: `modrinth-${entry.name}`,
          name: metadata?.name || entry.name,
          launcher: "modrinth",
          minecraftPath,
          version: metadata?.version
        });
      }
    } catch {}
    return instances;
  }
};

